/**
 * services/api.js
 * Capa de comunicación con el backend
 * Centraliza todas las llamadas a la API REST
 */

import axios from 'axios';

// Base URL del backend (en desarrollo usa el proxy de package.json)
const BASE_URL = process.env.REACT_APP_API_URL || '';

const api = axios.create({
  baseURL: BASE_URL,
  headers: { 'Content-Type': 'application/json' }
});

/**
 * getNormativas()
 * Obtiene el listado de normativas disponibles (sin preguntas)
 * @returns {Promise<Array>} Lista de { id, nombre, descripcion }
 */
export const getNormativas = async () => {
  const { data } = await api.get('/normativas');
  return data.data;
};

/**
 * getNormativa(id)
 * Obtiene una normativa completa con todos sus bloques y preguntas
 * @param {string} id - Identificador de la normativa (ej: "iso27001")
 * @returns {Promise<Object>} Normativa con bloques y preguntas
 */
export const getNormativa = async (id) => {
  const { data } = await api.get(`/normativas/${id}`);
  return data.data;
};

/**
 * enviarResultado(normativaId, respuestas)
 * Envía las respuestas al backend para calcular el porcentaje
 * @param {string} normativaId - ID de la normativa evaluada
 * @param {Array} respuestas - [{ pregunta_id, valor }, ...]
 * @returns {Promise<Object>} { porcentaje, puntuacion_total, puntuacion_maxima, mensaje }
 */
export const enviarResultado = async (normativaId, respuestas) => {
  const payload = {
    normativa: normativaId,
    respuestas: respuestas
  };
  const { data } = await api.post('/resultado', payload);
  return data.data;
};
